<?php require_once __DIR__.'/includes/init.php'; if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Metode tidak diizinkan.');} verify_csrf(); try { if(!empty($_SESSION['user_id'])) { $pdo=db_login(); $s=$pdo->prepare('INSERT INTO tb_log_aktivitas (id_user,aktivitas) VALUES (?,?)'); $s->execute([(int)$_SESSION['user_id'],'Logout']); } } catch(Throwable $e){error_log('[ParkirSTRD logout] '.$e->getMessage());} $_SESSION=[]; if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',(time()-42000),$p['path'],$p['domain']??'',(bool)$p['secure'],(bool)$p['httponly']);} session_destroy(); header('Location: '.url('login.php'));exit;